/** The preset package a consumer installs. */
export const CSHARP_PRESET_DIRECTORY = "node_modules/csharp-config-avi12";

/** The repo's own exemptions and options, at the repo root. */
export const CSHARP_LOCAL_FILE = "avi12-csharp.local.json";

/** The folder that holds the generated analyzer inputs, so the repo root keeps only `.editorconfig` and the props. */
export const CSHARP_SUPPORT_DIRECTORY = ".avi12-csharp";

const GENERATED_BANNER =
  "Generated by avi12-lint csharp-config from csharp-config-avi12 and avi12-csharp.local.json; do not edit";
const PROPS_IMPORT = `${CSHARP_SUPPORT_DIRECTORY}/analyzers.props`;
const SEVERITIES = new Set(["error", "warning", "suggestion", "silent", "none"]);
const LOCAL_KEYS = new Set([
  "options",
  "sections",
  "diagnostics",
  "directories",
  "files",
  "generatedPaths",
  "properties",
  "banned",
  "unbanned",
  "thresholds",
  "targets"
]);
const SONAR_RULE = /^S\d{3,4}$/;
const METRICS_RULE = /^CA\d{4}$/;

function isReasoned(reason) {
  return typeof reason === "string" && reason.trim() !== "";
}

function escapeXml(text) {
  return text.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
}

function validateEntries({ entries, label, shape }) {
  const problems = [];
  for (const [key, entry] of Object.entries(entries ?? {})) {
    const problem = shape(entry);
    if (problem) {
      problems.push(`${CSHARP_LOCAL_FILE}: ${label} "${key}" ${problem}`);
    }
  }

  return problems;
}

function diagnosticProblem(entry) {
  if (!SEVERITIES.has(entry?.severity)) {
    return `needs a severity of ${[...SEVERITIES].join(", ")}`;
  }

  return isReasoned(entry.reason) ? undefined : "needs a reason";
}

function reasonProblem(entry) {
  return isReasoned(entry?.reason) ? undefined : "needs a reason";
}

function valueProblem(entry) {
  const isNumber = typeof entry?.value === "number" && Number.isFinite(entry.value);
  if (!isNumber) {
    return "needs a numeric value";
  }

  return isReasoned(entry.reason) ? undefined : "needs a reason";
}

function validateLocal(local) {
  const problems = [];
  for (const key of Object.keys(local)) {
    if (!LOCAL_KEYS.has(key)) {
      problems.push(`${CSHARP_LOCAL_FILE}: unknown key "${key}"`);
    }
  }

  problems.push(
    ...validateEntries({
      entries: local.diagnostics,
      label: "diagnostics",
      shape: diagnosticProblem
    }),
    ...validateEntries({
      entries: local.generatedPaths,
      label: "generatedPaths",
      shape: entry => (isReasoned(entry) ? undefined : "needs a reason")
    }),
    ...validateEntries({
      entries: local.properties,
      label: "properties",
      shape: reasonProblem
    }),
    ...validateEntries({
      entries: local.options,
      label: "options",
      shape: reasonProblem
    }),
    ...validateEntries({
      entries: local.thresholds,
      label: "thresholds",
      shape: valueProblem
    }),
    ...validateEntries({
      entries: local.unbanned,
      label: "unbanned",
      shape: entry => (isReasoned(entry) ? undefined : "needs a reason")
    })
  );
  for (const [file, config] of Object.entries(local.files ?? {})) {
    problems.push(
      ...validateEntries({
        entries: config,
        label: `files "${file}"`,
        shape: diagnosticProblem
      })
    );
  }

  for (const [directory, config] of Object.entries(local.directories ?? {})) {
    problems.push(
      ...validateEntries({
        entries: config.diagnostics,
        label: `directories "${directory}" diagnostics`,
        shape: diagnosticProblem
      })
    );
  }

  return problems;
}

function renderOptions(options) {
  return Object.entries(options).map(([key, value]) => `${key} = ${value}`);
}

function sectionLines({ glob, options }) {
  return ["", `[${glob}]`, ...renderOptions(options)];
}

function diagnosticLines(diagnostics) {
  return Object.entries(diagnostics).flatMap(([id, { severity, reason }]) => {
    const isCategory = id.startsWith("category-");
    const key = isCategory ? `dotnet_analyzer_diagnostic.${id}.severity` : `dotnet_diagnostic.${id}.severity`;
    return [...(reason ? [`# ${id}: ${reason}`] : []), `${key} = ${severity}`];
  });
}

function namingLines(naming) {
  return Object.entries(naming).flatMap(
    ([name, { symbols, style, severity, capitalization, prefix, wordSeparator, comment }]) => {
      const symbolLines = Object.entries(symbols).map(
        ([key, value]) => `dotnet_naming_symbols.${name}.${key} = ${value}`
      );
      const styleLines = [
        `dotnet_naming_style.${style}.capitalization = ${capitalization}`,
        ...(prefix ? [`dotnet_naming_style.${style}.required_prefix = ${prefix}`] : []),
        ...(wordSeparator ? [`dotnet_naming_style.${style}.word_separator = ${wordSeparator}`] : [])
      ];
      return [
        ...(comment ? [`# ${comment}`] : []),
        ...symbolLines,
        ...styleLines,
        `dotnet_naming_rule.${name}.symbols = ${name}`,
        `dotnet_naming_rule.${name}.style = ${style}`,
        `dotnet_naming_rule.${name}.severity = ${severity}`
      ];
    }
  );
}

function mergeSections({ preset, local }) {
  const sections = new Map(Object.entries(preset).map(([glob, options]) => [glob, { ...options }]));
  for (const [glob, options] of Object.entries(local ?? {})) {
    sections.set(glob, {
      ...sections.get(glob),
      ...options
    });
  }

  return sections;
}

function sonarLines(sonar) {
  const kept = new Set(sonar.keep);
  const off = sonar.ids.filter(id => !kept.has(id));
  return [
    `# SonarAnalyzer.CSharp is referenced for ${sonar.keep.join(", ")} only; its other rules overlap the IDE, CA, Roslynator and Meziantou rules, which stay the owner of each rule`,
    ...off.map(id => `dotnet_diagnostic.${id}.severity = none`)
  ];
}

function renderEditorconfig({ style, diagnostics, sonar, local, generatedPaths }) {
  const options = { ...style.options };
  for (const [key, entry] of Object.entries(local.options ?? {})) {
    options[key] = entry.value;
  }

  const effective = {
    ...diagnostics,
    ...Object.fromEntries(
      Object.entries(local.diagnostics ?? {}).map(([id, entry]) => [
        id,
        {
          severity: entry.severity,
          reason: entry.reason
        }
      ])
    )
  };
  const optionReasons = Object.entries(local.options ?? {}).map(
    ([key, entry]) => `# ${key} is changed by this repo: ${entry.reason}`
  );
  const generatedSections = [
    ...style.generated.globs.map(glob => [
      glob,
      "Generated code (the XAML compiler, source generators) answers to nobody; the banned API analyzer does not skip it"
    ]),
    ...Object.entries(generatedPaths ?? {})
  ].flatMap(([glob, reason]) => [
    "",
    `# ${reason}`,
    ...sectionLines({
      glob,
      options: style.generated.options
    }).slice(1)
  ]);
  const fileSections = Object.entries(local.files ?? {}).flatMap(([file, entries]) => [
    "",
    `[${file}]`,
    ...diagnosticLines(entries)
  ]);
  const commonSections = [
    ...mergeSections({
      preset: style.sections,
      local: local.sections
    })
  ].flatMap(([glob, sectionOptions]) =>
    sectionLines({
      glob,
      options: sectionOptions
    })
  );
  return `${[
    `# ${GENERATED_BANNER}`,
    "root = true",
    ...commonSections,
    "",
    "[*.cs]",
    ...renderOptions(options),
    ...optionReasons,
    "",
    ...namingLines(style.naming),
    "",
    ...sonarLines(sonar),
    ...diagnosticLines(effective),
    ...fileSections,
    ...generatedSections
  ].join("\n")}\n`;
}

function renderDirectoryEditorconfig({ diagnostics }) {
  return `${["", "[*.cs]", ...diagnosticLines(diagnostics)].join("\n").replace(/^\n/, `# ${GENERATED_BANNER}\n`)}\n`;
}

function renderProps({ analyzers, properties, local }) {
  const merged = {
    ...properties,
    ...Object.fromEntries(Object.entries(local.properties ?? {}).map(([name, entry]) => [name, entry.value]))
  };
  const propertyLines = Object.entries(merged).map(
    ([name, value]) => `    <${name}>${escapeXml(String(value))}</${name}>`
  );
  const reasonLines = Object.entries(local.properties ?? {}).map(
    ([name, entry]) => `    <!-- ${name} is changed by this repo: ${entry.reason} -->`
  );
  const packageLines = analyzers.map(
    ({ id, version }) =>
      `    <PackageReference Include="${id}" Version="${version}" PrivateAssets="all" IncludeAssets="runtime; build; native; contentfiles; analyzers" />`
  );
  return `${[
    "<Project>",
    `  <!-- ${GENERATED_BANNER} -->`,
    "  <PropertyGroup>",
    ...reasonLines,
    ...propertyLines,
    "  </PropertyGroup>",
    "  <ItemGroup>",
    ...packageLines,
    '    <AdditionalFiles Include="$(MSBuildThisFileDirectory)BannedSymbols.txt" />',
    '    <AdditionalFiles Include="$(MSBuildThisFileDirectory)CodeMetricsConfig.txt" />',
    '    <AdditionalFiles Include="$(MSBuildThisFileDirectory)SonarLint.xml" Link="SonarLint.xml" />',
    "  </ItemGroup>",
    "</Project>"
  ].join("\n")}\n`;
}

function renderRootProps() {
  return `${[
    "<Project>",
    `  <!-- ${GENERATED_BANNER} -->`,
    `  <Import Project="${PROPS_IMPORT}" />`,
    "</Project>"
  ].join("\n")}\n`;
}

function renderBanned({ banned, local }) {
  const removed = new Set(Object.keys(local.unbanned ?? {}));
  const merged = {
    ...banned,
    ...local.banned
  };
  return `${Object.entries(merged)
    .filter(([symbol]) => !removed.has(symbol))
    .map(([symbol, message]) => `${symbol};${message}`)
    .join("\n")}\n`;
}

function numericThresholds({ local, pattern }) {
  return Object.entries(local.thresholds ?? {}).filter(
    ([id, entry]) => pattern.test(id) && typeof entry.value === "number"
  );
}

function renderMetrics({ thresholds, local }) {
  const merged = {
    ...thresholds.codeMetrics,
    ...Object.fromEntries(
      numericThresholds({
        local,
        pattern: METRICS_RULE
      }).map(([id, entry]) => [id, entry.value])
    )
  };
  return `${Object.entries(merged)
    .map(([id, value]) => `${id}: ${value}`)
    .join("\n")}\n`;
}

function renderSonar({ thresholds, local }) {
  const merged = {
    ...thresholds.sonar,
    ...Object.fromEntries(
      numericThresholds({
        local,
        pattern: SONAR_RULE
      }).map(([id, entry]) => {
        const [parameter] = Object.keys(thresholds.sonar[id] ?? { max: 0 });
        return [id, { [parameter]: entry.value }];
      })
    )
  };
  const rules = Object.entries(merged).map(
    ([id, parameters]) =>
      `    <Rule><Key>${id}</Key><Parameters>${Object.entries(parameters)
        .map(([key, value]) => `<Parameter><Key>${key}</Key><Value>${value}</Value></Parameter>`)
        .join("")}</Parameters></Rule>`
  );
  return `${[
    '<?xml version="1.0" encoding="utf-8"?>',
    `<!-- ${GENERATED_BANNER} -->`,
    "<AnalysisInput>",
    "  <Rules>",
    ...rules,
    "  </Rules>",
    "</AnalysisInput>"
  ].join("\n")}\n`;
}

/**
 * The preset `planCsharpConfig` takes, assembled from the preset package's five JSON files: `readJson(file)` answers
 * the parsed text of `analyzers.json`, `style.json`, `diagnostics.json`, `sonar.json` or `banned.json`. Pure given
 * `readJson`.
 */
export function csharpPreset(readJson) {
  const analyzers = readJson("analyzers.json");
  const diagnostics = readJson("diagnostics.json");
  return {
    analyzers: analyzers.packages,
    properties: analyzers.properties,
    formatExcludes: analyzers.formatExcludes,
    style: readJson("style.json"),
    diagnostics: diagnostics.diagnostics,
    thresholds: diagnostics.thresholds,
    sonar: readJson("sonar.json"),
    banned: readJson("banned.json")
  };
}

/**
 * Works out the files `avi12-lint csharp-config` writes: `.editorconfig` (style, naming, one severity per rule, and
 * the reason a rule is off), `.avi12-csharp/analyzers.props` (the analyzer package references and project
 * properties), `BannedSymbols.txt`, `CodeMetricsConfig.txt`, `SonarLint.xml`, a `Directory.Build.props` that imports
 * the props when the repo has none (`existing` is a Map of current text, a missing file undefined), and a nested
 * `.editorconfig` per `local.directories` entry. `preset` is `{ analyzers, style, diagnostics, banned, thresholds,
 * properties }`, the parsed preset JSON. `local` holds the repo's exemptions, each with a reason. Returns
 * `{ files: Map<name, text>, problems }`. Pure.
 */
export function planCsharpConfig({ preset, local = {}, existing = new Map() }) {
  const problems = validateLocal(local);
  const files = new Map([
    [
      ".editorconfig",
      renderEditorconfig({
        style: preset.style,
        diagnostics: preset.diagnostics,
        sonar: preset.sonar,
        local,
        generatedPaths: local.generatedPaths
      })
    ],
    [
      `${CSHARP_SUPPORT_DIRECTORY}/analyzers.props`,
      renderProps({
        analyzers: preset.analyzers,
        properties: preset.properties,
        local
      })
    ],
    [
      `${CSHARP_SUPPORT_DIRECTORY}/BannedSymbols.txt`,
      renderBanned({
        banned: preset.banned,
        local
      })
    ],
    [
      `${CSHARP_SUPPORT_DIRECTORY}/CodeMetricsConfig.txt`,
      renderMetrics({
        thresholds: preset.thresholds,
        local
      })
    ],
    [
      `${CSHARP_SUPPORT_DIRECTORY}/SonarLint.xml`,
      renderSonar({
        thresholds: preset.thresholds,
        local
      })
    ]
  ]);
  const rootProps = existing.get("Directory.Build.props");
  const isOwnProps = rootProps === undefined || rootProps.includes(GENERATED_BANNER);
  if (isOwnProps) {
    files.set("Directory.Build.props", renderRootProps());
  } else if (!rootProps.includes(PROPS_IMPORT)) {
    problems.push(`Directory.Build.props must import ${PROPS_IMPORT}: <Import Project="${PROPS_IMPORT}" />`);
  }

  for (const [directory, config] of Object.entries(local.directories ?? {})) {
    files.set(`${directory}/.editorconfig`, renderDirectoryEditorconfig({ diagnostics: config.diagnostics ?? {} }));
  }

  return {
    files,
    problems
  };
}

/** The paths whose current text (`existing`, a Map; a missing file is undefined) differs from what is wanted. */
export function staleCsharpFiles({ files, existing }) {
  return [...files].filter(([path, text]) => existing.get(path) !== text).map(([path]) => path);
}
